import{_ as l,l as n,o as a,c as s,v as t,p as i,x as o,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"后缀自动机","description":"","frontmatter":{"title":"后缀自动机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suffix-automaton.md","filePath":"cs/suffix-automaton.md","lastUpdated":1789023840000}'),c={name:"cs/suffix-automaton.md"};function u(h,e,A,f,_,T){const r=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="后缀自动机" tabindex="-1">后缀自动机 <a class="header-anchor" href="#后缀自动机" aria-label="Permalink to &quot;后缀自动机&quot;">​</a></h1><div class="epigraph"><p>把「结束位置集合相同」的子串收成一个状态；转移是加一个字符，后缀链指向更短的同类。</p><footer>—— 据 Blumer et al., The Smallest Automaton Recognizing the Subwords of a Text, J. ACM 1985；Crochemore and Rytter；Gusfield 整理</footer></div><p><a href="/cs/suffix-tree">上一课</a> 节点对应分支子串，状态数线性但常比自动机多。接受 \\(T\\) 的全体子串（或全体后缀）的最小 DFA 是后缀自动机（SAM / DAWG）。本课不画 Ukkonen 活动点。缺口是 endpos 等价类：线性状态、线性转移（固定字母表）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>子串 \\(u,v\\) 若在 \\(T\\) 中每次出现结束下标集合相同，则它们应同一状态。状态的 <code>len</code> 是该类最长串长度；后缀链接指向次长可能的另一类。在线加字符：克隆节点以保持确定性与最小化直觉。缺口是<strong>用等价类而不是每条后缀一条叶</strong>，从而子串计数、不同子串个数、首次出现在 DAG 上线性做。</p><p><span class="marginnote">Blumer et al. 1985, <em>JACM</em>。状态 \\(\\le 2n-1\\)，转移 \\(\\le 3n-4\\)（二字母等经典界）。构造在线 \\(O(n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护 last 状态。加字符 \\(c\\)：新建 \\(p\\)，沿后缀链补转移，必要时 clone。查询子串：从初始状态走 \\(|P|\\) 步。不同子串数：对转移 DAG 做路径计数（每状态 \\(\\mathrm{len}-\\mathrm{len}(link)\\)）。</p>',8)),(a(),i(m,null,{default:o(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EP%5B%22endpos%20%E7%9B%B8%E5%90%8C%22%5D%20--%3E%20ST%5B%22SAM%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20ST%20--%3E%20TR%5B%22%E5%8A%A0%E5%AD%97%E7%AC%A6%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20ST%20--%3E%20LK%5B%22suffix%20link%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与后缀树：存在互转；SAM 更省，后缀树更好报告出现位置几何（子树）。与 KMP：KMP 只要模式的前缀函数，SAM 索引整篇 \\(T\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小化接受全部子串的自动机本质唯一（同构）。clone 保证不破坏已有更短串的转移。实现用 map 或数组转移。不要把 SAM 当通用正则引擎——字母表与文本固定。</p><p>回文不是 endpos 能直接给的结构；下一课回文自动机（eertree）另建失配。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 SAM 与后缀树的同构证明写完。动态删前缀属变体。大字母表转移不是数组。</p><p>后课默认：子串自动机用 SAM。回文串全体用回文树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SAM：endpos 等价类 DFA，线性规模。</li><li>后缀链 + 克隆完成在线构造。</li><li>回文结构下一课另建。</li><li>出处：Blumer et al., <em>JACM</em>, 1985；Crochemore；Gusfield。</li></ul>',9))])}const B=l(c,[["render",u]]);export{x as __pageData,B as default};
